import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {2, 6, 9};
        int[] b = {1, 3, 4, 8};
        int[] merged = new int[a.length + b.length];
        int i = 0, j = 0, k = 0;
        while (i < a.length && j < b.length) {
            merged[k++] = a[i] <= b[j] ? a[i++] : b[j++];
        }
        while (i < a.length) {
            merged[k++] = a[i++];
        }
        while (j < b.length) {
            merged[k++] = b[j++];
        }
        System.out.println(Arrays.toString(merged));
    }
}
